nta.declaration:

/// ----- ** GLOBAL CONSTANTS
/*
    if F != 0, 
    `NodeFaultyNomination`, `NodeFaultyBallot` should be added in System declarations.
*/
const int THR = 100; // quorum threshold number
const int N = 5; // total number of nodes
const int F = 4; // total number of faulty nodes
const int V = 1; // maximum number of values in nomination state

const int INFINITY = 15; // _Boundary_
const int MAXCNT = 14;  // cur_nRound, cur_b_cnt, SCPBallot.counter (INFINITY - 1: ??)

const int SLOTMAX = V-1; // slot max index


// ** states for NominationBallot
const int SCPPrepare = 0;
const int SCPCommit = 1;
const int SCPExternalize = 2;


/// ------ ** TYPE DEFINITIONS

typedef int[0,N-F-1] n_id; // node id (0 to n-f-1)
typedef int[N-F,N-1] f_id; // fault node id (n-f to n-1)
typedef int[0,V-1] v_id; // value id (0 to v-1)
typedef int[0,SLOTMAX] s_id; // slot id
typedef int[0,N-1] t_id; // tick id

typedef struct {
    int[0,N] threshold;
    int[0,N] validators[N]; // reserving as many as N, stores ids
} SCPQuorumSlice;

// nomination
typedef struct {
    bool voted[V];
    bool accepted[V];
} SCPNominationState;

// ballot
typedef struct {
    int[0,INFINITY] counter;
    bool value[V];
} SCPBallot;

typedef struct {
    /* `curState`
        SCPPrepare = 0;
        SCPCommit = 1;
        SCPExternalize = 2;
    */
    int[0,2] curState;
    SCPBallot b;
    SCPBallot p;
    SCPBallot pp;
    SCPBallot h;
    SCPBallot c;
} SCPBallotState;
SCPBallotState ballotStates[N];


/// ------ ** Node configurations
/// ------- - modify here after change N, F values

// total participants involved for each value
// used in Slot management
///const int totalParticipants[V] = {5};
const int totalParticipants[V] = {N}; /// N(deadlock)? / N+1?

const bool NOVALUE[V] = // empty values (no values)
    {false};

bool higherlayerInput[N][V] =
    // values that nodes want to write on a block
    /// !!!: faulty nodes should not have any input values!
   {{true},
    {true},
    {true},
    {true},
    {true}};

SCPQuorumSlice qs[V][N] =
    // the entire of nodes are in one quorum
    // represents an invalid validator as N (e.g., {0, 1, N})
    // {threshold, {validators[N]}}
    {{{0, {0, 1, 2, 3, 4}},
      {0, {0, 1, 2, 3, 4}},
      {0, {0, 1, 2, 3, 4}},
      {0, {0, 1, 2, 3, 4}},
      {0, {0, 1, 2, 3, 4}}}};

SCPNominationState nominationStates[N] =
   {{{false}, {false}},
    {{false}, {false}},
    {{false}, {false}},
    {{false}, {false}},
    {{false}, {false}}};

bool nominatedValues[N][V] =
   {{false},
    {false},
    {false},
    {false},
    {false}};

bool ballotDone[N] =
    {false, false, false, false, false};

bool tickReady[N] =
    {true, true, true, true, true};

int[0,INFINITY] tickNomination[N] =
    {0, 0, 0, 0, 0};

int[0,INFINITY] tickBallot[N] =
    {0, 0, 0, 0, 0};

int[0,INFINITY] cur_nRound[N] = // current running nomination round states of each node
    {0, 0, 0, 0, 0};

int[0,INFINITY] cur_b_cnt[N] =
    {0, 0, 0, 0, 0};



/// ----- ** CHANNELS
chan sthNominated[N];
chan nominationDone[N];

chan slotDone;

chan tickAdvanceBallot[N];
chan tickAdvance[N];
chan tickAdvanceDone[N];

/// broadcast channels
broadcast chan slotSuccess;
broadcast chan slotFail;
broadcast chan slotTimeout;
broadcast chan slotStarted[SLOTMAX+1];

broadcast chan tickStart;
broadcast chan tickStop;
broadcast chan tickManagerStart; // for TickTestApp



/// ----- ** VARIABLES
int[0,SLOTMAX] slotCur = 0; // current slot pointer


/// ------ ** METHODS
bool isLessValue(const bool &valueL[V], const bool &valueR[V]) {
    // check if valueL < valueR

    int[-1, V-1] i;

    for (i = V-1; i >= 0; i--) {
        if (valueL[i] == false && valueR[i] == true) {
            return true;
        } else if (valueL[i] == true && valueR[i] == false) {
            return false;
        }
    }
    return false; // valueL == valueR
}

int getTotalValidators(const int[0,N] curNodeID) {
    /*
        parameter: int curNodeID (range: 0 to N)
        return: int

        Count how many validators `curNodeID` has.
    */
    int[0,N] totalValidators = 0;

    for (i : int[0,N-1]) {
        if (qs[slotCur][curNodeID].validators[i] != N) {
            totalValidators++;
        }
    }
    return totalValidators;
}

template.declaration:
bool isDone() {
    for (t : t_id) {
        if (tickReady[t] == true) {
            return false;
        }
    }
    return true;
} // test

void resetTick() {
    for (t : t_id) {
        tickReady[t] = true;
    }
}

int[0,N] cntSlotDone = 0;

bool hasHigherlayerInput() {
    for (n : n_id) {
        if (higherlayerInput[n] != NOVALUE) {
            return true;
        }
    }
    return false;
}

void clearInputs(const bool &value[V]) {
    for (v : v_id) {
        if (value[v]) {
            for (n : n_id) {
                higherlayerInput[n][v] = false;
            }
        }
    }
}

void doSuccess() {
    clearInputs(ballotStates[0].c.value);
    if (slotCur < SLOTMAX) {
        slotCur++;
    }
}

void doFail() {
    if (slotCur < SLOTMAX) {
        slotCur++;
    }
}

bool isAllAgreedLocal(int[0,N-1] nID) {
    bool value[V] = NOVALUE;

    for (n : n_id) {
        if (qs[slotCur][nID].validators[n] != N) {
            if (value == NOVALUE) {
                value = ballotStates[qs[slotCur][nID].validators[n]].c.value;
            }
            else {
                if (ballotStates[qs[slotCur][nID].validators[n]].c.value != value) {
                    return false;
                }
            }
        }
    }

    return true;
}

void resetNominationState() {
    /*
        A method to reset nomination state
        when a state goes back to `StartNomination`
    */
    cur_nRound[myID] = 0;
    tickNomination[myID] = 0;

    for (v : v_id) {
        nominatedValues[myID][v] = false;
        nominationStates[myID].voted[v] = false;
        nominationStates[myID].accepted[v] = false;
    }
}

void initNominationState() {
    /*
        A method to init nomination state
        when a state starts from `StartNomination` to `NominationStarted`
    */
    int[0,N] totalValidators = getTotalValidators(myID);

    if (qs[slotCur][myID].threshold == 0) { 
        // update a threshold in `qs` for nodeID (the template parameter)
        int minQuorumCount = totalValidators*THR/100 + 1;
        qs[slotCur][myID].threshold = (minQuorumCount >= totalValidators) 
                                        ? totalValidators 
                                        : minQuorumCount ;
    }
}

void processMessageNomination(bool hasNominatedValues) {
    int[0,N] cntValues = 0; // node count
    int[0,N] cntValues_qs = 0; // node count in quorum slice

    // blocking threshold check for accept nomination
    for (v : v_id) {
        cntValues = 0;

        // how many validators have accepted on `v`
        /* 
          For the current node
          - qs[slotCur][myID]: quorum slice
          - qs[slotCur][myID].validators[n]: a validator
          - qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id]: a nested validator (validator's validator)
        */

        for (id : int[0,N-1]) {
            if (
                qs[slotCur][myID].validators[id] != N
                && qs[slotCur][myID].validators[id] != myID
                && nominationStates[
                    qs[slotCur][myID].validators[id]
                ].accepted[v]
            ) {
                cntValues++; // count for acceptance of my validators on `v`
            }
        }

        // 
        if (
            cntValues > (getTotalValidators(myID) - qs[slotCur][myID].threshold) // blocking threshold
            && !nominationStates[myID].accepted[v]
        ) {
            nominationStates[myID].accepted[v] = true;
            nominationStates[myID].voted[v] = false;
        }
    }

    // quorum threshold check for vote nomination
    for (v : v_id) {
        cntValues = 0;

        for (id : int[0,N-1]) {
            if (qs[slotCur][myID].validators[id] != N) { 
                // check my validator's quorum slices
                cntValues_qs = 0;
                for (qs_id : int[0,N-1]) {
                    if (qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id] != N) {
                        if (
                            nominationStates[
                                qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id]
                            ].accepted[v]
                        ) {
                            cntValues_qs++;
                        }
                        else if (
                            nominationStates[
                                qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id]
                            ].voted[v]
                        ) {
                            cntValues_qs++;
                        }
                    }
                }

                if (cntValues_qs >= qs[slotCur][qs[slotCur][myID].validators[id]].threshold) {
                    cntValues++;
                }
            }
        }

        if (cntValues >= qs[slotCur][myID].threshold
            && !nominationStates[myID].accepted[v]) {
            nominationStates[myID].accepted[v] = true;
            nominationStates[myID].voted[v] = false;
        }
    }

    // quorum threshold check for accept nomination
    for (v : v_id) {
        cntValues = 0;

        for (id : int[0,N-1]) {
            if (qs[slotCur][myID].validators[id] != N) {
                cntValues_qs = 0;

                // check my validator's quorum slices
                for (qs_id : int[0,N-1]) {
                    if (qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id] != N) {
                        if (
                            nominationStates[
                                qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id]
                            ].accepted[v]
                        ) {
                            cntValues_qs++;
                        }
                    }
                }

                if (cntValues_qs >= qs[slotCur][qs[slotCur][myID].validators[id]].threshold) {
                    cntValues++;
                }
            }
        }

        if (cntValues >= qs[slotCur][myID].threshold) {
            if (!nominationStates[myID].accepted[v]) {
                nominationStates[myID].accepted[v] = true;
                nominationStates[myID].voted[v] = false;
            }

            if (!nominatedValues[myID][v]) {
                nominatedValues[myID][v] = true;
            }
        }
    }
}

int getHighestPriorityNode(int[0,MAXCNT] cur_round_in) {
    int[0,N] highest = cur_round_in % getTotalValidators(myID);
    int[0,N] current = 0;

    for (id : n_id) {
        if (qs[slotCur][myID].validators[id] != N) {
            if (current == highest) { 
                return qs[slotCur][myID].validators[id];
            }
            else {
                current++;
            }
        }
    }

    return myID;
}

void getMyHigherlayerInput() {
    for (v : v_id) {
        if (higherlayerInput[myID][v]
            && !nominationStates[myID].accepted[v]
            && !nominationStates[myID].voted[v]) {
            nominationStates[myID].voted[v] = true;
            return;
        }
    }
}

void doEchoing(int[0,N] nodeIDHighest) {
    /*
        For v-th value,
        if (highest node `voted` or `accepted` on it) and 
            nodeID(current node) has not voted or accepted on it,

        nodeID follows the highest node's decision.
    */
    for (v : v_id) {
        if (
            (nominationStates[nodeIDHighest].accepted[v]
                || nominationStates[nodeIDHighest].voted[v])
            && !nominationStates[myID].accepted[v]
            && !nominationStates[myID].voted[v]
        ) {
            nominationStates[myID].voted[v] = true;
        }
    }
}

void newRound(bool hasNominatedValues) {
    int[0,N] nodeIDHighest;

    // check if itself exists in its quorum slice
    if (qs[slotCur][myID].validators[myID] == myID) {

        // if its nomination tick reaches its current round value
        if (tickNomination[myID] == cur_nRound[myID]) {

            // nomination message passing
            processMessageNomination(hasNominatedValues);

            // mark as proceeding next round
            if (cur_nRound[myID]<MAXCNT) {
                cur_nRound[myID]++;
            }

            // only if it does not have nominated values
            // if it has some, it won't suggest or vote for new values
            if (!hasNominatedValues) {
                // get a leader
                nodeIDHighest = getHighestPriorityNode(cur_nRound[myID]);
                if (nodeIDHighest == myID) {
                    // if leader is self, get and vote for a higher layer input.
                    getMyHigherlayerInput();
                }
                else {
                    // else, vote for the leader's value
                    doEchoing(nodeIDHighest);
                }
            }
            // reset its nomination tick counter
            tickNomination[myID] = 0;
        }
        // else, increase the tick
        if (tickNomination[myID] < cur_nRound[myID]) {
            tickNomination[myID]++;
        }
    }
}

void resetNominationState() {
    /*
        A method to reset nomination state
        when a state goes back to `StartNomination`
    */
    cur_nRound[myID] = 0;
    tickNomination[myID] = 0;

    for (v : v_id) {
        nominatedValues[myID][v] = false;
        nominationStates[myID].voted[v] = false;
        nominationStates[myID].accepted[v] = false;
    }
}

void initNominationState() {
    /*
        A method to init nomination state
        when a state starts from `StartNomination` to `NominationStarted`
    */
    int[0,N] totalValidators = getTotalValidators(myID);

    if (qs[slotCur][myID].threshold == 0) { 
        // update a threshold in `qs` for nodeID (the template parameter)
        int minQuorumCount = totalValidators*THR/100 + 1;
        qs[slotCur][myID].threshold = (minQuorumCount >= totalValidators) 
                                        ? totalValidators 
                                        : minQuorumCount ;
    }
}

void processMessageNomination(bool hasNominatedValues) {
    int[0,N] cntValues = 0; // node count
    int[0,N] cntValues_qs = 0; // node count in quorum slice

    // blocking threshold check for accept nomination
    for (v : v_id) {
        cntValues = 0;

        // how many validators have accepted on `v`
        /* 
          For the current node
          - qs[slotCur][myID]: quorum slice
          - qs[slotCur][myID].validators[n]: a validator
          - qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id]: a nested validator (validator's validator)
        */

        for (id : int[0,N-1]) {
            if (
                qs[slotCur][myID].validators[id] != N
                && qs[slotCur][myID].validators[id] != myID
                && nominationStates[
                    qs[slotCur][myID].validators[id]
                ].accepted[v]
            ) {
                cntValues++; // count for acceptance of my validators on `v`
            }
        }
        /// ** ----- FAULTY ACTION APPLICATION POINT ---- ** ///
        if (
            cntValues > (getTotalValidators(myID) - qs[slotCur][myID].threshold) // blocking threshold
            && !nominationStates[myID].accepted[v]
        ) {
            nominationStates[myID].accepted[v] = true; 
            nominationStates[myID].voted[v] = false;
        }

    }

    // quorum threshold check for vote nomination
    for (v : v_id) {
        cntValues = 0;

        for (id : int[0,N-1]) {
            if (qs[slotCur][myID].validators[id] != N) { 
                // check my validator's quorum slices
                cntValues_qs = 0;
                for (qs_id : int[0,N-1]) {
                    if (qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id] != N) {
                        if (
                            nominationStates[
                                qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id]
                            ].accepted[v]
                        ) {
                            cntValues_qs++;
                        }
                        else if (
                            nominationStates[
                                qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id]
                            ].voted[v]
                        ) {
                            cntValues_qs++;
                        }
                    }
                }

                if (cntValues_qs >= qs[slotCur][qs[slotCur][myID].validators[id]].threshold) {
                    cntValues++;
                }
            }
        }
        /// ** ----- FAULTY ACTION APPLICATION POINT ---- ** ///
        if (cntValues >= qs[slotCur][myID].threshold
            && !nominationStates[myID].accepted[v]) {
            nominationStates[myID].accepted[v] = true;
            nominationStates[myID].voted[v] = false;
        }
    }

    // quorum threshold check for accept nomination
    for (v : v_id) {
        cntValues = 0;

        for (id : int[0,N-1]) {
            if (qs[slotCur][myID].validators[id] != N) {
                cntValues_qs = 0;

                // check my validator's quorum slices
                for (qs_id : int[0,N-1]) {
                    if (qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id] != N) {
                        if (
                            nominationStates[
                                qs[slotCur][qs[slotCur][myID].validators[id]].validators[qs_id]
                            ].accepted[v]
                        ) {
                            cntValues_qs++;
                        }
                    }
                }

                if (cntValues_qs >= qs[slotCur][qs[slotCur][myID].validators[id]].threshold) {
                    cntValues++;
                }
            }
        }
        /// ** ----- FAULTY ACTION APPLICATION POINT ---- ** ///
        if (cntValues >= qs[slotCur][myID].threshold) {
            if (!nominationStates[myID].accepted[v]) {
                nominationStates[myID].accepted[v] = true;
                nominationStates[myID].voted[v] = false;
            }

            if (!nominatedValues[myID][v]) {
                nominatedValues[myID][v] = true;
            }
        }
    }
}

int getHighestPriorityNode(int[0,MAXCNT] cur_round_in) {
    int[0,N] highest = cur_round_in % getTotalValidators(myID);
    int[0,N] current = 0;

    for (id : n_id) {
        if (qs[slotCur][myID].validators[id] != N) {
            if (current == highest) { 
                return qs[slotCur][myID].validators[id];
            }
            else {
                current++;
            }
        }
    }

    return myID;
}

void getMyHigherlayerInput() {
    for (v : v_id) {
        if (higherlayerInput[myID][v]
            && !nominationStates[myID].accepted[v]
            && !nominationStates[myID].voted[v]) {
            nominationStates[myID].voted[v] = true;
            return;
        }
    }
}

void doEchoing(int[0,N] nodeIDHighest) {
    /*
        For v-th value,
        if (highest node `voted` or `accepted` on it) and 
            nodeID(current node) has not voted or accepted on it,

        nodeID follows the highest node's decision.
    */
    for (v : v_id) {
        if (
            (nominationStates[nodeIDHighest].accepted[v]
                || nominationStates[nodeIDHighest].voted[v])
            && !nominationStates[myID].accepted[v]
            && !nominationStates[myID].voted[v]
        ) {
            nominationStates[myID].voted[v] = true;
        }
    }
}

void newRound(bool hasNominatedValues) {
    int[0,N] nodeIDHighest;

    // check if itself exists in its quorum slice
    if (qs[slotCur][myID].validators[myID] == myID) {

        // if its nomination tick reaches its current round value
        if (tickNomination[myID] == cur_nRound[myID]) {

            // nomination message passing
            processMessageNomination(hasNominatedValues);

            // mark as proceeding next round
            if (cur_nRound[myID]<MAXCNT) {
                cur_nRound[myID]++;
            }

            // only if it does not have nominated values
            // if it has some, it won't suggest or vote for new values
            if (!hasNominatedValues) {

                /// ** ----- FAULTY ACTION APPLICATION POINT ---- ** ///
                // get a leader
                nodeIDHighest = getHighestPriorityNode(cur_nRound[myID]);
                if (nodeIDHighest == myID) {
                    // if leader is self, get and vote for a higher layer input.
                    getMyHigherlayerInput();
                }
                else {
                    // else, vote for the leader's value
                    doEchoing(nodeIDHighest);
                }
            }
            // reset its nomination tick counter
            tickNomination[myID] = 0;
        }
        // else, increase the tick
        if (tickNomination[myID] < cur_nRound[myID]) {
            tickNomination[myID]++;
        }
    }
}

/// ----- ** HELPER FUNCTIONS
void sortArr(int[0,N*3] len, int[0,INFINITY]& arr[N*3]) {
    int[0,N*3] i, j, maxIndex;
    int[0,INFINITY] temp;

    for (i=0; i<len; i++) {
        temp = arr[i];
        maxIndex = i;
        for (j=i+1; j<len; j++) {
            if (temp <= arr[j]) {
                temp = arr[j];
                maxIndex = j;
            }
        }
        arr[maxIndex] = arr[i];
        arr[i] = temp;
    }
}

/// ----- ** Ballot FUNCTIONS
void initBallotState() {
    cur_b_cnt[myID] = 1;
    ballotStates[myID].b.counter = 1;

    for (v : v_id) {
        if (nominatedValues[myID][v] == true 
        && ballotStates[myID].b.value[v] == false) {
            ballotStates[myID].b.value[v] = true;
            return;
        }
    }
}

void resetBallotState() {
    cur_b_cnt[myID] = 0;
    tickBallot[myID] = 0;
    ballotDone[myID] = false;

    ballotStates[myID].curState = SCPPrepare;
    ballotStates[myID].b.counter = 0;
    ballotStates[myID].b.value = NOVALUE;
    ballotStates[myID].p.counter = 0;
    ballotStates[myID].p.value = NOVALUE;
    ballotStates[myID].pp.counter = 0;
    ballotStates[myID].pp.value = NOVALUE;
    ballotStates[myID].h.counter = 0;
    ballotStates[myID].h.value = NOVALUE;
    ballotStates[myID].c.counter = 0;
    ballotStates[myID].c.value = NOVALUE;
}

void updateBValue() {
    if (ballotStates[myID].h.value != NOVALUE) {
        // if `h` is NOT empty
        ballotStates[myID].b.value = ballotStates[myID].h.value;

    } else if (nominatedValues[myID] != NOVALUE) {

        for (v : v_id) {
            if (nominatedValues[myID][v] == true 
                && ballotStates[myID].b.value[v] == false) {

                ballotStates[myID].b.value[v] = true;
                return;
            }
        }
    }
    else if (ballotStates[myID].p.value != NOVALUE) {
        // if `p` is NOT empty
        ballotStates[myID].b.value = ballotStates[myID].p.value;
    }
}

bool checkAcceptedPrepareQuorum(int[0,N] nodeIndex, const SCPBallot &candidate) {
    int[0,N] cntQuorumTH = 0;
    bool isVBlocked = false;

    for (n : int[0,N-1]) {
        if (N - n + cntQuorumTH < qs[slotCur][nodeIndex].threshold) {
            return false;
        }
        if (qs[slotCur][nodeIndex].validators[n] != N) {
            isVBlocked = false;

            // on `qs[slotCur][nodeIndex].validators[n]`
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPPrepare
            ) {
                if (
                    ( // p
                        ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter != 0
                        && (ballotStates[qs[slotCur][nodeIndex].validators[n]].p.value == candidate.value
                            && ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter >= candidate.counter)
                    ) 
                    || ( // pp
                        ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.counter != 0
                        && (ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.value == candidate.value
                            && ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.counter >= candidate.counter)
                    )
                ) {
                    if (qs[slotCur][nodeIndex].validators[n] != nodeIndex) {
                        cntQuorumTH++;
                        isVBlocked = true;
                    }
                }
                if (!isVBlocked
                    && (ballotStates[qs[slotCur][nodeIndex].validators[n]].b.value == candidate.value
                        && ballotStates[qs[slotCur][nodeIndex].validators[n]].b.counter >= candidate.counter)) {
                    cntQuorumTH++;
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPCommit
            ) {
                if ( // p
                    ballotStates[qs[slotCur][nodeIndex].validators[n]].p.value == candidate.value
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter >= candidate.counter
                ) {
                    if (qs[slotCur][nodeIndex].validators[n] != nodeIndex) {
                        cntQuorumTH++;
                        isVBlocked = true;
                    }
                }
                if (!isVBlocked
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].b.value == candidate.value) {
                    cntQuorumTH++;
                }
            }
            else { /// Phase: SCPExternalize
                if ( // c
                    ballotStates[qs[slotCur][nodeIndex].validators[n]].c.value == candidate.value
                ) {
                    if (qs[slotCur][nodeIndex].validators[n] != nodeIndex) {
                        cntQuorumTH++;
                        isVBlocked = true;
                    }
                }
                if (!isVBlocked
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].c.value == candidate.value) {
                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= qs[slotCur][nodeIndex].threshold) {
                return true;
            }
        }
    }

    return false;
}

bool checkAcceptedPrepare(const SCPBallot &candidate) {
    int[0,N] cntVBlockTH = 0;
    int[0,N] cntQuorumTH = 0;

    if (/// Phase: SCPPrepare
        ballotStates[myID].curState == SCPCommit
    ) {
        if (!(ballotStates[myID].p.value == candidate.value
            && ballotStates[myID].p.counter < candidate.counter)) {
            return false;
        }
    }

    if (ballotStates[myID].pp.counter != 0
        && (ballotStates[myID].pp.counter > candidate.counter
            || (ballotStates[myID].pp.counter == candidate.counter
                && !(isLessValue(ballotStates[myID].pp.value, candidate.value))))) { // ballotStates[myID].pp.value >= candidate.value
        return false;
    }

    if (ballotStates[myID].p.counter != 0
        && (ballotStates[myID].p.value == candidate.value
            && ballotStates[myID].p.counter >= candidate.counter)) {
        return false;
    }

    for (n : int[0,N-1]) {
        // on `qs[slotCur][nodeIndex].validators[n]`
        if (qs[slotCur][myID].validators[n] != N) {
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPPrepare
            ) {
                if (
                    ( // p
                        ballotStates[qs[slotCur][myID].validators[n]].p.counter != 0
                        && (ballotStates[qs[slotCur][myID].validators[n]].p.value == candidate.value
                            && ballotStates[qs[slotCur][myID].validators[n]].p.counter >= candidate.counter)
                    ) 
                    || ( // pp
                        ballotStates[qs[slotCur][myID].validators[n]].pp.counter != 0
                            && (ballotStates[qs[slotCur][myID].validators[n]].pp.value == candidate.value
                            && ballotStates[qs[slotCur][myID].validators[n]].pp.counter >= candidate.counter)
                    )
                ) {
                    if (qs[slotCur][myID].validators[n] != myID) {
                        cntVBlockTH++;
                    }
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPCommit
            ) {
                if ( // p
                    ballotStates[qs[slotCur][myID].validators[n]].p.value == candidate.value
                    && ballotStates[qs[slotCur][myID].validators[n]].p.counter >= candidate.counter
                ) {
                    if (qs[slotCur][myID].validators[n] != myID) {
                        cntVBlockTH++;
                    }
                }
            }
            else {  /// Phase: SCPExternalize
                if (ballotStates[qs[slotCur][myID].validators[n]].c.value == candidate.value) {
                    if (qs[slotCur][myID].validators[n] != myID) {
                        cntVBlockTH++;
                    }
                }
            }

            if (cntVBlockTH > getTotalValidators(myID) - qs[slotCur][myID].threshold) {
                return true;
            }

            if (checkAcceptedPrepareQuorum(n, candidate)) {
                cntQuorumTH++;
            }

            if (cntQuorumTH >= qs[slotCur][myID].threshold) {
                return true;
            }
        }
    }

    return false;
}

bool attemptAcceptPrepare(SCPBallot &acceptedBallot, SCPBallot &newMessageBallots[3]) {
    bool isAgreed = false;
    bool hasNewAcceptedPrepare = false;
    SCPBallot tempBallot;

    for (n : int[0,N-1]) {
        if (qs[slotCur][myID].validators[n] != N) {
            isAgreed = false;
            tempBallot.counter = 0;
            tempBallot.value = NOVALUE;

            if (/// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPPrepare
            ) {
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (
                            ballotStates[qs[slotCur][myID].validators[n]].b.value == newMessageBallots[j].value
                            && ballotStates[qs[slotCur][myID].validators[n]].b.counter <= newMessageBallots[j].counter
                        ) {

                            isAgreed = checkAcceptedPrepare(ballotStates[qs[slotCur][myID].validators[n]].b);
                            if (isAgreed) {
                                tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].b.counter;
                                tempBallot.value = ballotStates[qs[slotCur][myID].validators[n]].b.value;

                            } else {
                                if (
                                    ballotStates[qs[slotCur][myID].validators[n]].p.counter != 0
                                    && (ballotStates[qs[slotCur][myID].validators[n]].p.value == newMessageBallots[j].value
                                        && ballotStates[qs[slotCur][myID].validators[n]].p.counter <= newMessageBallots[j].counter)
                                ) {

                                    isAgreed = checkAcceptedPrepare(ballotStates[qs[slotCur][myID].validators[n]].p);
                                    if (isAgreed) {
                                        tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].p.counter;
                                        tempBallot.value = ballotStates[qs[slotCur][myID].validators[n]].p.value;
                                    }
                                    else {
                                        if (
                                            ballotStates[qs[slotCur][myID].validators[n]].pp.counter != 0
                                            && (ballotStates[qs[slotCur][myID].validators[n]].pp.value == newMessageBallots[j].value
                                                && ballotStates[qs[slotCur][myID].validators[n]].pp.counter <= newMessageBallots[j].counter)
                                        ) {

                                            isAgreed = checkAcceptedPrepare(ballotStates[qs[slotCur][myID].validators[n]].pp);
                                            if (isAgreed) {
                                                tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].pp.counter;
                                                tempBallot.value = ballotStates[qs[slotCur][myID].validators[n]].pp.value;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPCommit
            ) {
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (ballotStates[qs[slotCur][myID].validators[n]].c.value == newMessageBallots[j].value) {

                            isAgreed = checkAcceptedPrepare(newMessageBallots[j]);
                            if (isAgreed) {
                                tempBallot.counter = newMessageBallots[j].counter;
                                tempBallot.value = newMessageBallots[j].value;
                            }
                            else {
                                if (ballotStates[qs[slotCur][myID].validators[n]].p.counter < newMessageBallots[j].counter) {
                                    tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].p.counter;
                                    tempBallot.value = newMessageBallots[j].value;
                                    isAgreed = checkAcceptedPrepare(tempBallot);
                                }
                            }
                        }
                    }
                }
            }
            else { /// Phase: SCPCommit
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (ballotStates[qs[slotCur][myID].validators[n]].c.value == newMessageBallots[j].value) {

                            isAgreed = checkAcceptedPrepare(newMessageBallots[j]);
                            if (isAgreed) {
                                tempBallot.counter = newMessageBallots[j].counter;
                                tempBallot.value = newMessageBallots[j].value;
                            }
                        }
                    }
                }
            }

            if (isAgreed) {
                hasNewAcceptedPrepare = true;
                if (
                    acceptedBallot.counter < tempBallot.counter
                    || (acceptedBallot.counter == tempBallot.counter
                        && isLessValue(acceptedBallot.value, tempBallot.value)) // acceptedBallot.value < tempBallot.value
                ) {
                    acceptedBallot.counter = tempBallot.counter;
                    acceptedBallot.value = tempBallot.value;
                }
            }
        }
    }

    return hasNewAcceptedPrepare;
}

bool checkConfirmedPrepareQuorum(int[0,N] nodeIndex, const SCPBallot &candidate) {
    int[0,N] cntQuorumTH = 0;

    for (n : int[0,N-1]) {
        if (N - n + cntQuorumTH < qs[slotCur][nodeIndex].threshold) {
            return false;
        }

        if (qs[slotCur][nodeIndex].validators[n] != N) {
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPPrepare
            ) {
                if (
                    ( // p
                        ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter != 0
                        && (ballotStates[qs[slotCur][nodeIndex].validators[n]].p.value == candidate.value
                            && ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter >= candidate.counter)
                    ) 
                    || ( // pp
                        ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.counter != 0
                        && (ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.value == candidate.value
                            && ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.counter >= candidate.counter)
                    )
                ) {
                    cntQuorumTH++;
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPCommit
            ) {
                if (ballotStates[qs[slotCur][nodeIndex].validators[n]].p.value == candidate.value
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter >= candidate.counter) {
                    cntQuorumTH++;
                }
            }
            else { /// Phase: SCPExternalize
                if (ballotStates[qs[slotCur][nodeIndex].validators[n]].c.value == candidate.value) {
                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= qs[slotCur][nodeIndex].threshold) {
                return true;
            }
        }
    }

    return false;
}

bool checkConfirmedPrepare(const SCPBallot &candidate) {
    int[0,N] cntQuorumTH = 0;

