bool attemptConfirmPrepare(SCPBallot &confirmedHBallot, SCPBallot &newMessageBallots[3]) {
    bool isAgreed = false;
    bool hasNewConfirmedPrepare = false;
    SCPBallot tempBallot;

    for (n : int[0,N-1]) {
        if (qs[slotCur][myID].validators[n] != N) {
            isAgreed = false;
            tempBallot.counter = 0;
            tempBallot.value = NOVALUE;
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPPrepare
            ) {
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if ( // p
                            ballotStates[qs[slotCur][myID].validators[n]].p.counter != 0
                             && (ballotStates[qs[slotCur][myID].validators[n]].p.value == newMessageBallots[j].value
                             && ballotStates[qs[slotCur][myID].validators[n]].p.counter <= newMessageBallots[j].counter)
                        ) {

                            isAgreed = checkConfirmedPrepare(ballotStates[qs[slotCur][myID].validators[n]].p);
                            if (isAgreed) {
                                tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].p.counter;
                                tempBallot.value = ballotStates[qs[slotCur][myID].validators[n]].p.value;
                            } else {
                                if ( // pp
                                    ballotStates[qs[slotCur][myID].validators[n]].pp.counter != 0 
                                    && (ballotStates[qs[slotCur][myID].validators[n]].pp.value == newMessageBallots[j].value 
                                        && ballotStates[qs[slotCur][myID].validators[n]].pp.counter <= newMessageBallots[j].counter)) {

                                    isAgreed = checkConfirmedPrepare(ballotStates[qs[slotCur][myID].validators[n]].pp);
                                    if (isAgreed) {
                                        tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].pp.counter;
                                        tempBallot.value = ballotStates[qs[slotCur][myID].validators[n]].pp.value;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPCommit
            ) {
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (ballotStates[qs[slotCur][myID].validators[n]].p.counter < newMessageBallots[j].counter) {

                            tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].p.counter;
                            tempBallot.value = newMessageBallots[j].value;
                            isAgreed = checkConfirmedPrepare(tempBallot);
                        }
                    }
                }
            }
            else { /// Phase: SCPExternalize
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (ballotStates[qs[slotCur][myID].validators[n]].c.value == newMessageBallots[j].value) {

                            isAgreed = checkConfirmedPrepare(newMessageBallots[j]);
                            if (isAgreed) {
                                tempBallot.counter = newMessageBallots[j].counter;
                                tempBallot.value = newMessageBallots[j].value;
                            }
                        }
                    }
                }
            }

            if (isAgreed) {
                if (ballotStates[myID].h.counter == 0
                    || (ballotStates[myID].h.counter < tempBallot.counter
                        || (ballotStates[myID].h.counter == tempBallot.counter
                            && isLessValue(ballotStates[myID].h.value, tempBallot.value)))) { // ballotStates[myID].h.value < tempBallot.value

                    hasNewConfirmedPrepare = true;
                    if (confirmedHBallot.counter == 0) {
                        confirmedHBallot.counter = tempBallot.counter;
                        confirmedHBallot.value = tempBallot.value;
                    } else {
                        if (confirmedHBallot.counter < tempBallot.counter
                            || (confirmedHBallot.counter == tempBallot.counter
                                && isLessValue(confirmedHBallot.value, tempBallot.value))) { // confirmedHBallot.value < tempBallot.value

                            confirmedHBallot.counter = tempBallot.counter;
                            confirmedHBallot.value = tempBallot.value;
                        }
                    }
                }
            }
        }
    }

    return hasNewConfirmedPrepare;
}

bool checkAcceptedCommitQuorum(int[0,N] nodeIndex, const bool &ballotValue[V], int[0,INFINITY] counterC, int[0,INFINITY] counterH) {
    int[0,N] cntQuorumTH = 0;
    bool isVBlocked = false;

    for (n : int[0,N-1]) {
        if (N - n + cntQuorumTH < qs[slotCur][nodeIndex].threshold) {
            return false;
        }

        if (qs[slotCur][nodeIndex].validators[n] != N) {
            isVBlocked = false;
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPPrepare
            ) {
                if (ballotStates[qs[slotCur][nodeIndex].validators[n]].b.value == ballotValue
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].h.counter >= counterH) {
                    cntQuorumTH++;
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPCommit
            ) {
                if (ballotStates[qs[slotCur][nodeIndex].validators[n]].b.value == ballotValue
                    && (ballotStates[qs[slotCur][nodeIndex].validators[n]].c.counter <= counterC
                        && ballotStates[qs[slotCur][nodeIndex].validators[n]].h.counter >= counterH)) {

                    cntQuorumTH++;
                    isVBlocked = true;
                }
                if (!isVBlocked
                    && (ballotStates[qs[slotCur][nodeIndex].validators[n]].b.value == ballotValue
                        && ballotStates[qs[slotCur][nodeIndex].validators[n]].c.counter <= counterC)) {

                    cntQuorumTH++;
                }
            }
            else { /// Phase: SCPExternalize
                if (ballotStates[qs[slotCur][nodeIndex].validators[n]].c.value == ballotValue
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].c.counter <= counterC) {

                    cntQuorumTH++;
                    isVBlocked = true;
                }
                if (!isVBlocked
                    && (ballotStates[qs[slotCur][nodeIndex].validators[n]].c.value == ballotValue
                        && ballotStates[qs[slotCur][nodeIndex].validators[n]].c.counter <= counterC)) {

                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= qs[slotCur][nodeIndex].threshold) {
                return true;
            }
        }
    }

    return false;
}

bool checkAcceptedCommit(const bool &ballotValue[V], int[0,INFINITY] counterC, int[0,INFINITY] counterH) {
    int[0,N] cntVBlockTH = 0;
    int[0,N] cntQuorumTH = 0;

    for (n : int[0,N-1]) {
        if (qs[slotCur][myID].validators[n] != N) {
            if (/// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPPrepare
            ) {
                // do nothing
            } else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPCommit
            ) {
                if (ballotStates[qs[slotCur][myID].validators[n]].b.value == ballotValue
                    && (ballotStates[qs[slotCur][myID].validators[n]].c.counter <= counterC
                        && ballotStates[qs[slotCur][myID].validators[n]].h.counter >= counterH)) {
                    cntVBlockTH++;
                }
            } else { /// Phase: SCPExternalize
                if (ballotStates[qs[slotCur][myID].validators[n]].c.value == ballotValue
                    && ballotStates[qs[slotCur][myID].validators[n]].c.counter <= counterC) {
                    cntVBlockTH++;
                }
            }

            if (cntVBlockTH > getTotalValidators(myID) - qs[slotCur][myID].threshold) {
                return true;
            }

            if (checkAcceptedCommitQuorum(n, ballotValue, counterC, counterH)) {
                cntQuorumTH++;
            }

            if (cntQuorumTH >= qs[slotCur][myID].threshold) {
                return true;
            }
        }
    }

    return false;
}

bool attemptAcceptCommit(SCPBallot &newMessageBallots[3], int[0,INFINITY] &acceptedCounterC, int[0,INFINITY] &acceptedCounterH) {
    int[0,N*3] k; // index for curBoundaries[N*3]
    int[0,INFINITY] curBoundaries[N*3];
    int[0,N*3] nextBoundary = 0;
    bool isAgreed = false;

    for (n : int[0,N-1]) {
        if (qs[slotCur][myID].validators[n] != N) {
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPPrepare
                && ballotStates[qs[slotCur][myID].validators[n]].b.value == newMessageBallots[0].value
            ) {
                if (ballotStates[qs[slotCur][myID].validators[n]].c.counter != 0) { // c
                    curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].c.counter;
                }
                if (ballotStates[qs[slotCur][myID].validators[n]].h.counter != 0) { // h
                    curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].h.counter;
                }

            } else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPCommit
                && ballotStates[qs[slotCur][myID].validators[n]].b.value == newMessageBallots[0].value
            ) {
                curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].c.counter;
                curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].h.counter;

            } else { /// Phase: SCPExternalize
                if (ballotStates[qs[slotCur][myID].validators[n]].c.value == newMessageBallots[0].value) {
                    curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].c.counter;
                    curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].h.counter;
                    curBoundaries[nextBoundary++] = INFINITY;
                }
            }
        }
    }

    // sort curBoundaries[0 .. nextBoundary-1]: highest first
    sortArr(nextBoundary, curBoundaries);

    k = 0;
    acceptedCounterC = 0;
    acceptedCounterH = 0;
    isAgreed = false;
    do {
        if (acceptedCounterH == 0) {// find the high boundary
            if (
                checkAcceptedCommit(newMessageBallots[0].value, curBoundaries[k], curBoundaries[k])
            ) {
                isAgreed = true;
                acceptedCounterH = curBoundaries[k];
                k++;
            } else {
                k++;
            }
        } else {// find the low boundary
            if (
                checkAcceptedCommit(newMessageBallots[0].value, curBoundaries[k], acceptedCounterH)
            ) {
                acceptedCounterC = curBoundaries[k];
                k = nextBoundary;
            } else {
                k++;
            }
        }
    } while (acceptedCounterC == 0 && k < nextBoundary);

    return isAgreed;
}

bool checkConfirmedCommitQuorum(int[0,N] nodeIndex, const bool &ballotValue[V], int[0,INFINITY] counterC, int[0,INFINITY] counterH) {
    int[0,N] cntQuorumTH = 0;

    for (n : int[0,N-1]) {
        if (N - n + cntQuorumTH < qs[slotCur][nodeIndex].threshold) {
            return false;
        }

        if (qs[slotCur][nodeIndex].validators[n] != N) {
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPPrepare
            ) {
                // do nothing
            } else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPCommit
            ) {

                if (ballotStates[qs[slotCur][nodeIndex].validators[n]].b.value == ballotValue
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].c.counter <= counterC
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].h.counter >= counterH) {
                    cntQuorumTH++;
                }
            } else { /// Phase: SCPExternalize

                if (ballotStates[qs[slotCur][nodeIndex].validators[n]].c.value == ballotValue
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].c.counter <= counterC) {
                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= qs[slotCur][nodeIndex].threshold) {
                return true;
            }
        }
    }

    return false;
}

bool checkConfirmedCommit(const bool &ballotValue[V], int[0,INFINITY] counterC, int[0,INFINITY] counterH) {
    int[0,N] cntQuorumTH = 0;

    for (n : int[0,N-1]) {
        if (qs[slotCur][myID].validators[n] != N) {
            if (N - n + cntQuorumTH < qs[slotCur][myID].threshold) {
                return false;
            }

            if (checkConfirmedCommitQuorum(n, ballotValue, counterC, counterH)) {
                cntQuorumTH++;
            }

            if (cntQuorumTH >= qs[slotCur][myID].threshold) {
                return true;
            }
        }
    }

    return false;
}

bool attemptConfirmCommit(SCPBallot &newMessageBallots[3], int[0,INFINITY] &acceptedCounterC, int[0,INFINITY] &acceptedCounterH) {
    int[0,N*3] k; // index for curBoundaries[N*3]
    int[0,INFINITY] curBoundaries[N*3];
    int[0,N*3] nextBoundary = 0;
    bool isAgreed = false;

    for (n : int[0,N-1]) {
        if (qs[slotCur][myID].validators[n] != N) {
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPPrepare
            ) {
                // do nothing
            } else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPCommit
                && ballotStates[qs[slotCur][myID].validators[n]].b.value == newMessageBallots[0].value
            ) {

                curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].c.counter;
                curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].h.counter;
            } else { /// Phase: SCPExternalize

                if (ballotStates[qs[slotCur][myID].validators[n]].c.value == newMessageBallots[0].value) {
                    curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].c.counter;
                    curBoundaries[nextBoundary++] = ballotStates[qs[slotCur][myID].validators[n]].h.counter;
                    curBoundaries[nextBoundary++] = INFINITY;
                }
            }
        }
    }

    // sort curBoundaries[0 .. nextBoundary-1]: highest first
    sortArr(nextBoundary, curBoundaries);

    k = 0;
    acceptedCounterC = 0;
    acceptedCounterH = 0;
    isAgreed = false;
    do {
        if (acceptedCounterH == 0) {// find the high boundary
            if (
                checkConfirmedCommit(newMessageBallots[0].value, curBoundaries[k], curBoundaries[k])
            ) {
                isAgreed = true;
                acceptedCounterH = curBoundaries[k];
                k++;
            } else {
                k++;
            }
        }
        else {// find the low boundary
            if (
                checkConfirmedCommit(newMessageBallots[0].value, curBoundaries[k], acceptedCounterH)
            ) {
                acceptedCounterC = curBoundaries[k];
                k = nextBoundary;
            } else {
                k++;
            }
        }
    } while (acceptedCounterC == 0 && k < nextBoundary);

    return isAgreed;
}

void processMessagePrepare() {
    bool hasNewBallot = false;
    int[0,N-1] newMessageNode = myID;
    int[0,N-1] newMessageNodeIndex = 0;
    int[0,N] current = 0;
    int[0,INFINITY] acceptedCounterC = 0;
    int[0,INFINITY] acceptedCounterH = 0;
    SCPBallot newBallot;
    SCPBallot newMessageBallots[3];

    newMessageNodeIndex = cur_b_cnt[myID] % getTotalValidators(myID);
    for (n : n_id) {
        if (qs[slotCur][myID].validators[n] != N) {
            if (current == newMessageNodeIndex) {
                newMessageNode = qs[slotCur][myID].validators[n];
            }
            else {
                current++;
            }
        }
    }
    if (ballotStates[qs[slotCur][myID].validators[newMessageNode]].b.counter < ballotStates[myID].b.counter) {
        return;
    }

    if (ballotStates[newMessageNode].curState == SCPPrepare) {
        /// Phase: SCPPrepare
        newMessageBallots[0].counter = ballotStates[newMessageNode].b.counter;
        newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        newMessageBallots[1].counter = ballotStates[newMessageNode].p.counter;
        newMessageBallots[1].value = ballotStates[newMessageNode].p.value;
        newMessageBallots[2].counter = ballotStates[newMessageNode].pp.counter;
        newMessageBallots[2].value = ballotStates[newMessageNode].pp.value;

    } else if (ballotStates[newMessageNode].curState == SCPCommit) {
        /// Phase: SCPCommit
        newMessageBallots[0].counter = ballotStates[newMessageNode].p.counter;
        newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        newMessageBallots[1].counter = INFINITY;
        newMessageBallots[1].value = ballotStates[newMessageNode].b.value;
        newMessageBallots[2].counter = 0;
        newMessageBallots[2].value = NOVALUE;

    } else {
        /// Phase: SCPExternalize
        newMessageBallots[0].counter = INFINITY;
        newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        newMessageBallots[1].counter = 0;
        newMessageBallots[1].value = NOVALUE;
        newMessageBallots[2].counter = 0;
        newMessageBallots[2].value = NOVALUE;
    }

    // blocking threshold check for b.counter

    // blocking threshold check for accept prepare ballots (attemptAcceptPrepare)
    // quorum threshold check for vote prepare ballots (attemptAcceptPrepare)
    newBallot.counter = 0;
    newBallot.value = NOVALUE;
    hasNewBallot = attemptAcceptPrepare(newBallot, newMessageBallots);

    if (hasNewBallot) {
        // update p or pp
        if (ballotStates[myID].p.counter == 0) {
            ballotStates[myID].p.counter = newBallot.counter;
            ballotStates[myID].p.value = newBallot.value;
        }
        else {
            if (
                ballotStates[myID].p.counter < newBallot.counter
                || (ballotStates[myID].p.counter == newBallot.counter
                    && isLessValue(ballotStates[myID].p.value, newBallot.value)) // ballotStates[myID].p.value < newBallot.value
            ) {

                if (ballotStates[myID].p.value != newBallot.value) {

                    ballotStates[myID].pp.counter = ballotStates[myID].p.counter;
                    ballotStates[myID].pp.value = ballotStates[myID].p.value;
                }
                ballotStates[myID].p.counter = newBallot.counter;
                ballotStates[myID].p.value = newBallot.value;
            } else if (
                ballotStates[myID].p.counter > newBallot.counter
                || (ballotStates[myID].p.counter == newBallot.counter
                    && isLessValue(newBallot.value, ballotStates[myID].p.value)) // ballotStates[myID].p.value > newBallot.value
            ) { 
                if (
                    ballotStates[myID].pp.counter == 0
                    || (ballotStates[myID].pp.counter < newBallot.counter
                        || (ballotStates[myID].pp.counter == newBallot.counter
                            && isLessValue(ballotStates[myID].pp.value, newBallot.value))) // ballotStates[myID].pp.value < newBallot.value
                ) { 
                    if (ballotStates[myID].p.value != newBallot.value) {

                        ballotStates[myID].pp.counter = newBallot.counter;
                        ballotStates[myID].pp.value = newBallot.value;
                    }
                }
            }
        }

        // clear c if required
        if (ballotStates[myID].c.counter != 0
            && ballotStates[myID].h.counter != 0
            && ((ballotStates[myID].p.counter != 0
                    && ballotStates[myID].h.value != ballotStates[myID].p.value
                    && ballotStates[myID].h.counter < ballotStates[myID].p.counter)
                || (ballotStates[myID].pp.counter != 0
                    && ballotStates[myID].h.value != ballotStates[myID].pp.value
                    && ballotStates[myID].h.counter < ballotStates[myID].pp.counter))) {

            ballotStates[myID].c.counter = 0;
            ballotStates[myID].c.value = NOVALUE;
        }
    }

    // quorum threshold check for accept prepare ballots (attemptConfirmPrepare)
    if (ballotStates[myID].p.counter != 0) {
        newBallot.counter = 0;
        newBallot.value = NOVALUE;
        hasNewBallot = attemptConfirmPrepare(newBallot, newMessageBallots);

        if (hasNewBallot) {
            // update h or c
            if (newBallot.counter != 0) {
                ballotStates[myID].h.counter = newBallot.counter;
                ballotStates[myID].h.value = newBallot.value;
                if (ballotStates[myID].c.counter == 0
                    && (ballotStates[myID].p.counter == 0
                        || !(ballotStates[myID].p.value != newBallot.value
                            && ballotStates[myID].p.counter <= newBallot.counter))
                    && (ballotStates[myID].pp.counter == 0
                        || !(ballotStates[myID].pp.value != newBallot.value
                            && ballotStates[myID].pp.counter <= newBallot.counter))
                    && (ballotStates[myID].b.counter < newBallot.counter
                        || (ballotStates[myID].b.counter == newBallot.counter
                            && !isLessValue(newBallot.value, ballotStates[myID].b.value)))) { // ballotStates[myID].b.value <= newBallot.value

                    ballotStates[myID].c.counter = newBallot.counter;
                    ballotStates[myID].c.value = newBallot.value;
                }
            }

            // bump b if required
            if (ballotStates[myID].b.counter == 0
                || (ballotStates[myID].b.counter < ballotStates[myID].h.counter
                    || (ballotStates[myID].b.counter == ballotStates[myID].h.counter
                        && isLessValue(ballotStates[myID].b.value, ballotStates[myID].h.value)))) { // ballotStates[myID].b.value < ballotStates[myID].h.value

                ballotStates[myID].b.counter = ballotStates[myID].h.counter;
                ballotStates[myID].b.value = ballotStates[myID].h.value;
            }
        }
    }

    // blocking threshold check for accept commit ballots (attemptAcceptCommit)
    // quorum threshold check for vote commit ballots (attemptAcceptCommit)
    if (ballotStates[newMessageNode].h.counter != 0) {
        newMessageBallots[0].counter = ballotStates[newMessageNode].h.counter;

        if (/// Phase: SCPExternalize
            ballotStates[newMessageNode].curState == SCPExternalize
        ) {
            newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        } else {
            newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        }

        hasNewBallot = attemptAcceptCommit(newMessageBallots, acceptedCounterC, acceptedCounterH);

        if (hasNewBallot) {
            if (acceptedCounterC == 0) {
                acceptedCounterC = acceptedCounterH;
            }

            ballotStates[myID].c.counter = acceptedCounterC;
            ballotStates[myID].c.value = newMessageBallots[0].value;
            ballotStates[myID].h.counter = acceptedCounterH;
            ballotStates[myID].h.value = newMessageBallots[0].value;
            ballotStates[myID].curState = SCPCommit;
            ballotStates[myID].pp.counter = 0;
            ballotStates[myID].pp.value = NOVALUE;
        }
    }

    if (ballotStates[myID].h.counter > ballotStates[myID].b.counter) {
        ballotStates[myID].b.counter = ballotStates[myID].h.counter;
        ballotStates[myID].b.value = ballotStates[myID].h.value;
    }
}

void processMessageCommit() {
    bool hasNewBallot = false;
    int[0,N-1] newMessageNode = myID;
    int[0,N-1] newMessageNodeIndex = 0;
    int[0,N] current = 0;
    int[0,INFINITY] acceptedCounterC = 0;
    int[0,INFINITY] acceptedCounterH = 0;
    SCPBallot newBallot;
    SCPBallot newMessageBallots[3];

    newMessageNodeIndex = cur_b_cnt[myID] % getTotalValidators(myID);
    for (n : n_id) {
        if (qs[slotCur][myID].validators[n] != N) {
            if (current == newMessageNodeIndex) {
                newMessageNode = qs[slotCur][myID].validators[n];
            }
            else {
                current++;
            }
        }
    }
    if (ballotStates[qs[slotCur][myID].validators[newMessageNode]].b.counter < ballotStates[myID].b.counter) {
        return;
    }

    if ( /// Phase: SCPPrepare
        ballotStates[newMessageNode].curState == SCPPrepare
    ) {
        newMessageBallots[0].counter = ballotStates[newMessageNode].b.counter;
        newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        newMessageBallots[1].counter = ballotStates[newMessageNode].p.counter;
        newMessageBallots[1].value = ballotStates[newMessageNode].p.value;
        newMessageBallots[2].counter = ballotStates[newMessageNode].pp.counter;
        newMessageBallots[2].value = ballotStates[newMessageNode].pp.value;

    } else if ( /// Phase: SCPCommit
        ballotStates[newMessageNode].curState == SCPCommit
    ) {
        newMessageBallots[0].counter = ballotStates[newMessageNode].p.counter;
        newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        newMessageBallots[1].counter = INFINITY;
        newMessageBallots[1].value = ballotStates[newMessageNode].b.value;
        newMessageBallots[2].counter = 0;
        newMessageBallots[2].value = NOVALUE;

    }
    else { /// Phase: SCPExternalize
        newMessageBallots[0].counter = INFINITY;
        newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        newMessageBallots[1].counter = 0;
        newMessageBallots[1].value = NOVALUE;
        newMessageBallots[2].counter = 0;
        newMessageBallots[2].value = NOVALUE;
    }

    // blocking threshold check for b.counter

    // blocking threshold check for accept prepare ballots (attemptAcceptPrepare)
    // quorum threshold check for vote prepare ballots (attemptAcceptPrepare)
    newBallot.counter = 0;
    newBallot.value = NOVALUE;
    hasNewBallot = attemptAcceptPrepare(newBallot, newMessageBallots);

    if (hasNewBallot) {
        // update p or pp
        if (ballotStates[myID].p.counter == 0) {

            ballotStates[myID].p.counter = newBallot.counter;
            ballotStates[myID].p.value = newBallot.value;
        }
        else {
            if (ballotStates[myID].p.counter < newBallot.counter
                || (ballotStates[myID].p.counter == newBallot.counter
                    && isLessValue(ballotStates[myID].p.value, newBallot.value))) { // ballotStates[myID].p.value < newBallot.value
                if (ballotStates[myID].p.value != newBallot.value) {
                    ballotStates[myID].pp.counter = ballotStates[myID].p.counter;
                    ballotStates[myID].pp.value = ballotStates[myID].p.value;
                }
                ballotStates[myID].p.counter = newBallot.counter;
                ballotStates[myID].p.value = newBallot.value;

            } else if (ballotStates[myID].p.counter > newBallot.counter
                || (ballotStates[myID].p.counter == newBallot.counter
                    && isLessValue(newBallot.value, ballotStates[myID].p.value))) { // ballotStates[myID].p.value > newBallot.value

                if (ballotStates[myID].pp.counter == 0
                    || (ballotStates[myID].pp.counter < newBallot.counter
                        || (ballotStates[myID].pp.counter == newBallot.counter
                            && isLessValue(ballotStates[myID].pp.value, newBallot.value)))) { // ballotStates[myID].pp.value < newBallot.value

                    if (ballotStates[myID].p.value != newBallot.value) {

                        ballotStates[myID].pp.counter = newBallot.counter;
                        ballotStates[myID].pp.value = newBallot.value;
                    }
                }
            }
        }
    }

    // blocking threshold check for accept commit ballots (attemptAcceptCommit)
    // quorum threshold check for vote commit ballots (attemptAcceptCommit)
    if (ballotStates[newMessageNode].h.counter != 0) {
        newMessageBallots[0].counter = ballotStates[newMessageNode].h.counter;

        if ( /// Phase: SCPExternalize
            ballotStates[newMessageNode].curState == SCPExternalize
        ) {
            newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        } else {
            newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        }

        hasNewBallot = attemptAcceptCommit(newMessageBallots, acceptedCounterC, acceptedCounterH);

        if (hasNewBallot) {
            if (acceptedCounterC == 0) {
                acceptedCounterC = acceptedCounterH;
            }

            ballotStates[myID].c.counter = acceptedCounterC;
            ballotStates[myID].c.value = newMessageBallots[0].value;
            ballotStates[myID].h.counter = acceptedCounterH;
            ballotStates[myID].h.value = newMessageBallots[0].value;
            ballotStates[myID].pp.counter = 0;
            ballotStates[myID].pp.value = NOVALUE;
        }
    }

    // quorum threshold check for accept commit ballots (attemptConfirmCommit)
    if ( // Phase not SCPPrepare
        ballotStates[newMessageNode].curState != SCPPrepare
    ) {

        newMessageBallots[0].counter = ballotStates[newMessageNode].h.counter;

        if ( /// Phase: SCPExternalize
            ballotStates[newMessageNode].curState == SCPExternalize
        ) {
            newMessageBallots[0].value = ballotStates[newMessageNode].c.value;
        } else { /// Phase: SCPCommit
            newMessageBallots[0].value = ballotStates[newMessageNode].b.value;
        }

        hasNewBallot = attemptConfirmCommit(newMessageBallots, acceptedCounterC, acceptedCounterH);

        if (hasNewBallot) {
            if (acceptedCounterC == 0) {
                acceptedCounterC = acceptedCounterH;
            }

            ballotStates[myID].c.counter = acceptedCounterC;
            ballotStates[myID].c.value = newMessageBallots[0].value;
            ballotStates[myID].h.counter = acceptedCounterH;
            ballotStates[myID].h.value = newMessageBallots[0].value;
            ballotStates[myID].curState = SCPExternalize;
            ballotStates[myID].b.counter = INFINITY;
        }
    }

    if (ballotStates[myID].h.counter > ballotStates[myID].b.counter) {

        ballotStates[myID].b.counter = ballotStates[myID].h.counter;
        ballotStates[myID].b.value = ballotStates[myID].h.value;
    }
}

void newBCounter() {
    if (tickBallot[myID] == cur_b_cnt[myID]) {
        if ( /// Phase: SCPPrepare
            ballotStates[myID].curState == SCPPrepare
        ) {
            processMessagePrepare();

            if (ballotStates[myID].b.counter<MAXCNT) {
                ballotStates[myID].b.counter++;
            }

            if (cur_b_cnt[myID] < MAXCNT) {
                cur_b_cnt[myID]++;
            }

            updateBValue();
        }
        else if ( /// Phase: SCPCommit
            ballotStates[myID].curState == SCPCommit
        ) {
            processMessageCommit();

            if (ballotStates[myID].b.counter<MAXCNT) {
                ballotStates[myID].b.counter++;
            }
            if (cur_b_cnt[myID] < MAXCNT) {
                cur_b_cnt[myID]++;
            }
            updateBValue();
        }
        else {/// Phase: SCPExternalize
            // do nothing
        }

        tickBallot[myID] = 0;
    }

    if (tickBallot[myID] < cur_b_cnt[myID]) {
        tickBallot[myID]++;
    }
}

/// ----- ** HELPER FUNCTIONS
void sortArr(int[0,N*3] len, int[0,INFINITY]& arr[N*3]) {
    int[0,N*3] i,j,maxIndex;
    int[0,INFINITY] temp;

    for (i=0; i<len; i++) {
        temp = arr[i];
        maxIndex = i;
        for (j=i+1; j<len; j++) {
            if (temp <= arr[j]) {
                temp = arr[j];
                maxIndex = j;
            }
        }
        arr[maxIndex] = arr[i];
        arr[i] = temp;
    }
}

/// ----- ** Ballot FUNCTIONS
void initBallotState() {
    cur_b_cnt[myID] = 1;
    ballotStates[myID].b.counter = 1;

    for (v : v_id) {
        if (nominatedValues[myID][v] == true 
        && ballotStates[myID].b.value[v] == false) {
            ballotStates[myID].b.value[v] = true;
            return;
        }
    }
}

void resetBallotState() {
    cur_b_cnt[myID] = 0;
    tickBallot[myID] = 0;
    ballotDone[myID] = false;

    ballotStates[myID].curState = SCPPrepare;
    ballotStates[myID].b.counter = 0;
    ballotStates[myID].b.value = NOVALUE;
    ballotStates[myID].p.counter = 0;
    ballotStates[myID].p.value = NOVALUE;
    ballotStates[myID].pp.counter = 0;
    ballotStates[myID].pp.value = NOVALUE;
    ballotStates[myID].h.counter = 0;
    ballotStates[myID].h.value = NOVALUE;
    ballotStates[myID].c.counter = 0;
    ballotStates[myID].c.value = NOVALUE;
}

void updateBValue() {
    if (ballotStates[myID].h.value != NOVALUE) {
        // if `h` is NOT empty
        ballotStates[myID].b.value = ballotStates[myID].h.value;

    } else if (nominatedValues[myID] != NOVALUE) {

        for (v : v_id) {
            if (nominatedValues[myID][v] == true 
                && ballotStates[myID].b.value[v] == false) {

                ballotStates[myID].b.value[v] = true;
                return;
            }
        }
    }
    else if (ballotStates[myID].p.value != NOVALUE) {
        // if `p` is NOT empty
        ballotStates[myID].b.value = ballotStates[myID].p.value;
    }
}

bool checkAcceptedPrepareQuorum(int[0,N] nodeIndex, const SCPBallot &candidate) {
    int[0,N] cntQuorumTH = 0;
    bool isVBlocked = false;

    for (n : int[0,N-1]) {
        if (N - n + cntQuorumTH < qs[slotCur][nodeIndex].threshold) {
            return false;
        }
        if (qs[slotCur][nodeIndex].validators[n] != N) {
            isVBlocked = false;

            // on `qs[slotCur][nodeIndex].validators[n]`
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPPrepare
            ) {
                if (
                    ( // p
                        ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter != 0
                        && (ballotStates[qs[slotCur][nodeIndex].validators[n]].p.value == candidate.value
                            && ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter >= candidate.counter)
                    ) || 
                    ( // pp
                        ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.counter != 0
                        && (ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.value == candidate.value
                            && ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.counter >= candidate.counter)
                    )
                ) {
                    if (qs[slotCur][nodeIndex].validators[n] != nodeIndex) {
                        cntQuorumTH++;
                        isVBlocked = true;
                    }
                }
                if (!isVBlocked
                    && (ballotStates[qs[slotCur][nodeIndex].validators[n]].b.value == candidate.value
                        && ballotStates[qs[slotCur][nodeIndex].validators[n]].b.counter >= candidate.counter)) {
                    cntQuorumTH++;
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPCommit
            ) {
                if ( // p
                    ballotStates[qs[slotCur][nodeIndex].validators[n]].p.value == candidate.value
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter >= candidate.counter
                ) {
                    if (qs[slotCur][nodeIndex].validators[n] != nodeIndex) {
                        cntQuorumTH++;
                        isVBlocked = true;
                    }
                }
                if (!isVBlocked
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].b.value == candidate.value) {
                    cntQuorumTH++;
                }
            }
            else { /// Phase: SCPExternalize
                if ( // c
                    ballotStates[qs[slotCur][nodeIndex].validators[n]].c.value == candidate.value
                ) {
                    if (qs[slotCur][nodeIndex].validators[n] != nodeIndex) {
                        cntQuorumTH++;
                        isVBlocked = true;
                    }
                }
                if (!isVBlocked
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].c.value == candidate.value) {
                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= qs[slotCur][nodeIndex].threshold) {
                return true;
            }
        }
    }

    return false;
}

bool checkAcceptedPrepare(const SCPBallot &candidate) {
    int[0,N] cntVBlockTH = 0;
    int[0,N] cntQuorumTH = 0;

    if (/// Phase: SCPPrepare
        ballotStates[myID].curState == SCPCommit
    ) {
        if (!(ballotStates[myID].p.value == candidate.value
            && ballotStates[myID].p.counter < candidate.counter)) {
            return false;
        }
    }

    if (ballotStates[myID].pp.counter != 0
        && (ballotStates[myID].pp.counter > candidate.counter
            || (ballotStates[myID].pp.counter == candidate.counter
                && !(isLessValue(ballotStates[myID].pp.value, candidate.value))))) { // ballotStates[myID].pp.value >= candidate.value
        return false;
    }

    if (ballotStates[myID].p.counter != 0
        && (ballotStates[myID].p.value == candidate.value
            && ballotStates[myID].p.counter >= candidate.counter)) {
        return false;
    }

    for (n : int[0,N-1]) {
        // on `qs[slotCur][nodeIndex].validators[n]`
        if (qs[slotCur][myID].validators[n] != N) {
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPPrepare
            ) {
                if (
                    ( // p
                        ballotStates[qs[slotCur][myID].validators[n]].p.counter != 0
                        && (ballotStates[qs[slotCur][myID].validators[n]].p.value == candidate.value
                            && ballotStates[qs[slotCur][myID].validators[n]].p.counter >= candidate.counter)
                    ) || 
                    ( // pp
                        ballotStates[qs[slotCur][myID].validators[n]].pp.counter != 0
                            && (ballotStates[qs[slotCur][myID].validators[n]].pp.value == candidate.value
                            && ballotStates[qs[slotCur][myID].validators[n]].pp.counter >= candidate.counter)
                    )
                ) {
                    if (qs[slotCur][myID].validators[n] != myID) {
                        cntVBlockTH++;
                    }
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPCommit
            ) {
                if ( // p
                    ballotStates[qs[slotCur][myID].validators[n]].p.value == candidate.value
                    && ballotStates[qs[slotCur][myID].validators[n]].p.counter >= candidate.counter
                ) {
                    if (qs[slotCur][myID].validators[n] != myID) {
                        cntVBlockTH++;
                    }
                }
            }
            else {  /// Phase: SCPExternalize
                if (ballotStates[qs[slotCur][myID].validators[n]].c.value == candidate.value) {
                    if (qs[slotCur][myID].validators[n] != myID) {
                        cntVBlockTH++;
                    }
                }
            }

            if (cntVBlockTH > getTotalValidators(myID) - qs[slotCur][myID].threshold) {
                return true;
            }

            if (checkAcceptedPrepareQuorum(n, candidate)) {
                cntQuorumTH++;
            }

            if (cntQuorumTH >= qs[slotCur][myID].threshold) {
                return true;
            }
        }
    }

    return false;
}

bool attemptAcceptPrepare(SCPBallot &acceptedBallot, SCPBallot &newMessageBallots[3]) {
    bool isAgreed = false;
    bool hasNewAcceptedPrepare = false;
    SCPBallot tempBallot;

    for (n : int[0,N-1]) {
        if (qs[slotCur][myID].validators[n] != N) {
            isAgreed = false;
            tempBallot.counter = 0;
            tempBallot.value = NOVALUE;

            if (/// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPPrepare
            ) {
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (
                            ballotStates[qs[slotCur][myID].validators[n]].b.value == newMessageBallots[j].value
                            && ballotStates[qs[slotCur][myID].validators[n]].b.counter <= newMessageBallots[j].counter
                        ) {

                            isAgreed = checkAcceptedPrepare(ballotStates[qs[slotCur][myID].validators[n]].b);
                            if (isAgreed) {
                                tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].b.counter;
                                tempBallot.value = ballotStates[qs[slotCur][myID].validators[n]].b.value;

                            } else {
                                if (
                                    ballotStates[qs[slotCur][myID].validators[n]].p.counter != 0
                                    && (ballotStates[qs[slotCur][myID].validators[n]].p.value == newMessageBallots[j].value
                                        && ballotStates[qs[slotCur][myID].validators[n]].p.counter <= newMessageBallots[j].counter)
                                ) {

                                    isAgreed = checkAcceptedPrepare(ballotStates[qs[slotCur][myID].validators[n]].p);
                                    if (isAgreed) {
                                        tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].p.counter;
                                        tempBallot.value = ballotStates[qs[slotCur][myID].validators[n]].p.value;
                                    }
                                    else {
                                        if (
                                            ballotStates[qs[slotCur][myID].validators[n]].pp.counter != 0
                                            && (ballotStates[qs[slotCur][myID].validators[n]].pp.value == newMessageBallots[j].value
                                                && ballotStates[qs[slotCur][myID].validators[n]].pp.counter <= newMessageBallots[j].counter)
                                        ) {

                                            isAgreed = checkAcceptedPrepare(ballotStates[qs[slotCur][myID].validators[n]].pp);
                                            if (isAgreed) {
                                                tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].pp.counter;
                                                tempBallot.value = ballotStates[qs[slotCur][myID].validators[n]].pp.value;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][myID].validators[n]
                ].curState == SCPCommit
            ) {
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (ballotStates[qs[slotCur][myID].validators[n]].c.value == newMessageBallots[j].value) {

                            isAgreed = checkAcceptedPrepare(newMessageBallots[j]);
                            if (isAgreed) {
                                tempBallot.counter = newMessageBallots[j].counter;
                                tempBallot.value = newMessageBallots[j].value;
                            }
                            else {
                                if (ballotStates[qs[slotCur][myID].validators[n]].p.counter < newMessageBallots[j].counter) {
                                    tempBallot.counter = ballotStates[qs[slotCur][myID].validators[n]].p.counter;
                                    tempBallot.value = newMessageBallots[j].value;
                                    isAgreed = checkAcceptedPrepare(tempBallot);
                                }
                            }
                        }
                    }
                }
            }
            else { /// Phase: SCPCommit
                for (j : int[0,2]) {
                    if (!isAgreed && newMessageBallots[j].counter != 0) {
                        if (ballotStates[qs[slotCur][myID].validators[n]].c.value == newMessageBallots[j].value) {

                            isAgreed = checkAcceptedPrepare(newMessageBallots[j]);
                            if (isAgreed) {
                                tempBallot.counter = newMessageBallots[j].counter;
                                tempBallot.value = newMessageBallots[j].value;
                            }
                        }
                    }
                }
            }

            if (isAgreed) {
                hasNewAcceptedPrepare = true;
                if (
                    acceptedBallot.counter < tempBallot.counter
                    || (acceptedBallot.counter == tempBallot.counter
                        && isLessValue(acceptedBallot.value, tempBallot.value)) // acceptedBallot.value < tempBallot.value
                ) {
                    acceptedBallot.counter = tempBallot.counter;
                    acceptedBallot.value = tempBallot.value;
                }
            }
        }
    }

    return hasNewAcceptedPrepare;
}

bool checkConfirmedPrepareQuorum(int[0,N] nodeIndex, const SCPBallot &candidate) {
    int[0,N] cntQuorumTH = 0;

    for (n : int[0,N-1]) {
        if (N - n + cntQuorumTH < qs[slotCur][nodeIndex].threshold) {
            return false;
        }

        if (qs[slotCur][nodeIndex].validators[n] != N) {
            if ( /// Phase: SCPPrepare
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPPrepare
            ) {
                if (
                    ( // p
                        ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter != 0
                        && (ballotStates[qs[slotCur][nodeIndex].validators[n]].p.value == candidate.value
                            && ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter >= candidate.counter)
                    ) || 
                    ( // pp
                        ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.counter != 0
                        && (ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.value == candidate.value
                            && ballotStates[qs[slotCur][nodeIndex].validators[n]].pp.counter >= candidate.counter)
                    )
                ) {
                    cntQuorumTH++;
                }
            }
            else if ( /// Phase: SCPCommit
                ballotStates[
                    qs[slotCur][nodeIndex].validators[n]
                ].curState == SCPCommit
            ) {
                if (ballotStates[qs[slotCur][nodeIndex].validators[n]].p.value == candidate.value
                    && ballotStates[qs[slotCur][nodeIndex].validators[n]].p.counter >= candidate.counter) {
                    cntQuorumTH++;
                }
            }
            else { /// Phase: SCPExternalize
                if (ballotStates[qs[slotCur][nodeIndex].validators[n]].c.value == candidate.value) {
                    cntQuorumTH++;
                }
            }

            if (cntQuorumTH >= qs[slotCur][nodeIndex].threshold) {
                return true;
            }
        }
    }

    return false;
}

